    func.argtypes = [ctypes.POINTER(GSLFilterGaussianWorkspace), ctypes.POINTER(GSLVector), ctypes.POINTER(GSLVector), ctypes.POINTER(GSLVector), ctypes.POINTER(GSLVector)]
    func.restype = None
    return func(workspace, x, y, dy, d2y)

