def generate_halton_point(dimension):
    if dimension < 1 or dimension > 1229:
        raise ValueError("Dimension must be between 1 and 1229.")

    # Allocate memory for the Halton point
    halton_point = (ctypes.c_double * dimension)()

    # Create a Halton sequence state
    gsl_rng_type* T;
    gsl_rng* r;
    gsl_rng_env_setup();
    T = gsl_rng_default;
    r = gsl_rng_alloc(T);

    # Initialize the Halton sequence state with a seed (e.g., 0)
    gsl_rng_set(r, 0);

    # Generate the Halton point
    generate_halton_point(dimension, r, halton_point)

    # Free the Halton sequence state
    gsl_rng_free(r)

    # Convert the Halton point to a list and return it
    return [float(halton_point[i]) for i in range(dimension)]

