class GSLBlock:
    def __init__(self):
        self.block = None

    def allocate(self, n):
        self.block = gsl.gsl_block_alloc(ctypes.c_size_t(n))
        if not self.block:
            return False
        return True

    def calloc(self):
        if not self.block:
            return False
        if gsl.gsl_block_calloc(ctypes.byref(self.block)) != 0:
            return False
        return True

    def free(self):
        if not self.block:
            return False
        gsl.gsl_block_free(ctypes.byref(self.block))
        return True

def allocate_and_free_block(n):
    block = GSLBlock()
    if not block.allocate(n) or not block.calloc() or not block.free():
        return False
    return True

