class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                ("params", ctypes.c_void_p)]

def func_wrapper(x, params):
    py_func = ctypes.cast(params, ctypes.py_object).value
    return py_func(x)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    func = gsl_function(func_wrapper, ctypes.py_object(py_func))
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    ws = gsl.gsl_integration_romberg_alloc(n)
    status = gsl.gsl_integration_romberg(ws, func.function, a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(abserr))
    gsl.gsl_integration_romberg_free(ws)
    if status != 0:
        raise Exception(f"Integration failed with status {status}")
    return result.value, int(1e6 / abs(abserr.value))

